Section Steps2.
  Context {R : Type}.
  Variable A : astate.
  Hypothesis HW : WF A.
  Implicit Types (s : mstate) (P : R -> mstate -> Prop).

  Lemma ts_lhu_fact : forall s a v (k : word -> M R) P,
    Rep A (ms_mem s) -> WIN s -> has A (FCT a 2 v) -> 0 <= v < 2^16 ->
    tsafe (k (Z_to_bv 64 v) s) P ->
    tsafe ((x <- m_lhu (Z_to_bv 64 a) ;; k x) s) P.
Proof using HW MLok.
