  (* [comment removed for export] *)
  Lemma ts_ld_ctx_nn : forall s ck (k : word -> M R) P,
    Rep A (ms_mem s) -> WIN s -> cvalid ck -> clen ck = 8 -> 0 <= a_ctx A ck ->
    tsafe (k (Z_to_bv 64 (a_ctx A ck)) s) P ->
